&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de magus&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_magus_0&quot; href=&quot;#Les_arch&#233;types_de_magus_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-Occulte-(Magus).html&quot; title=&quot;Archer occulte&quot;&gt;Archer occulte&lt;/a&gt; (HOTS)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;l&#233;mentaire-(Magus).html&quot; title=&quot;Chevalier &#233;l&#233;mentaire (magus)&quot;&gt;Chevalier &#233;l&#233;mentaire&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Suli-(Race).html&quot; title=&quot;Les sulis&quot;&gt;Suli&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Danse-Sort-(Magus).html&quot; title=&quot;Danse-sort&quot;&gt;Danse-sort&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-De-La-Tour-(Magus).html&quot; title=&quot;D&#233;fenseur de la tour&quot;&gt;D&#233;fenseur de la tour&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;corcheur-Fi&#233;lon-(Magus).html&quot; title=&quot;&#201;corcheur fi&#233;lon&quot;&gt;&#201;corcheur fi&#233;lon&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;Tieffelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;sot&#233;riste-(Magus).html&quot; title=&quot;&#201;sot&#233;riste&quot;&gt;&#201;sot&#233;riste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forge&#226;me-(Magus).html&quot; title=&quot;Forge&#226;me&quot;&gt;Forge&#226;me&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kensai-(Magus).html&quot; title=&quot;Kensai&quot;&gt;Kensai&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lameli&#233;-(Magus).html&quot; title=&quot;Lameli&#233;&quot;&gt;Lameli&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lamesprit-(Magus).html&quot; title=&quot;Lamesprit&quot;&gt;Lamesprit&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lamesort-(Magus).html&quot; title=&quot;Lamesort&quot;&gt;Lamesort&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lanceur-De-Mal&#233;fices-(Magus).html&quot; title=&quot;Lanceur de mal&#233;fices&quot;&gt;Lanceur de mal&#233;fices&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mage-De-Bataille-Blind&#233;-(Magus).html&quot; title=&quot;Mage de bataille blind&#233;&quot;&gt;Mage de bataille blind&#233;&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myrmidarque-(Magus).html&quot; title=&quot;Myrmidarque&quot;&gt;Myrmidarque&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rejeton-&#201;trange-(Magus).html&quot; title=&quot;Rejeton &#233;trange&quot;&gt;Rejeton &#233;trange&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Skirnir-(Magus).html&quot; title=&quot;Skirnir&quot;&gt;Skirnir&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sp&#233;cialiste-Du-B&#226;ton-(Magus).html&quot; title=&quot;Sp&#233;cialiste du b&#226;ton&quot;&gt;Sp&#233;cialiste du b&#226;ton&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Le forge&#226;me a appris comment faire passer l’essence magique brute de son &#226;me dans son armement pour lui donner une puissance incomparable et combiner ainsi les arts mystiques aux arts guerriers dans une osmose parfaite.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Incantation r&#233;duite&lt;a class=&quot;headeranchor&quot; id=&quot;Incantation_r&#233;duite_0&quot; href=&quot;#Incantation_r&#233;duite_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le forge&#226;me lance un sort de moins de chaque niveau de sort que les &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;magi&lt;/a&gt; ordinaires. Si ce changement fait passer son nombre de sorts &#224; 0, il peut lancer des sorts de ce niveau uniquement si son &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; lui accorde des sorts suppl&#233;mentaires pour ce niveau.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pacte magique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Pacte_magique_Sur_1&quot; href=&quot;#Pacte_magique_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 1, le forge&#226;me gagne une arme comme &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#PACTEMAGIQUE&quot; title=&quot;Le magicien&quot;&gt;objet f&#233;tiche&lt;/a&gt;. Ce pouvoir fonctionne comme celui de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; mais le magus se lie obligatoirement &#224; une arme.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Combat magique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Combat_magique_Sur_2&quot; href=&quot;#Combat_magique_Sur_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le forge&#226;me peut utiliser ce &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#COMBATMAGIQUE&quot; title=&quot;Le magus&quot;&gt;pouvoir&lt;/a&gt; uniquement quand il manie son arme f&#233;tiche.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Frappe magique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Frappe_magique_Sur_3&quot; href=&quot;#Frappe_magique_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le forge&#226;me peut utiliser ce &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#FRAPPEMAGIQUE&quot; title=&quot;Le magus&quot;&gt;pouvoir&lt;/a&gt; uniquement quand il manie son arme f&#233;tiche.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;tre forgeron (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;tre_forgeron_Ext_4&quot; href=&quot;#Ma&#238;tre_forgeron_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le forge&#226;me ajoute son niveau de magus &#224; ses tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; pour cr&#233;er une armure, un bouclier ou une arme. Ce bonus s’applique aux tests de comp&#233;tence qui accompagnent l’utilisation du don &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Magiques.html#ARMES&quot; title=&quot;Cr&#233;ation d&amp;#39;objets magiques&quot;&gt;Cr&#233;ation d’armes&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Magiques.html#ARMURES&quot; title=&quot;Cr&#233;ation d&amp;#39;objets magiques&quot;&gt;armures magiques&lt;/a&gt;. Au niveau 7, le forge&#226;me utilise le dixi&#232;me de la valeur en po des objets ordinaires qu’il fabrique pour d&#233;terminer le temps que cela lui prend et il met deux fois moins de temps que les autres pour enchanter les armes et les armures. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#RESERVEDECONNAISSANCES&quot; title=&quot;Le magus&quot;&gt;r&#233;serve de connaissances&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pacte renforc&#233; (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Pacte_renforc&#233;_Sur_5&quot; href=&quot;#Pacte_renforc&#233;_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un forge&#226;me de niveau 4 peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#RESERVEMAGIQUE&quot; title=&quot;Le magus&quot;&gt;r&#233;serve magique&lt;/a&gt; pour augmenter la solidit&#233; et les points de vie de son arme f&#233;tiche, d’un nombre de point &#233;gal &#224; son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;magus&lt;/a&gt;. Ces points de vie persistent jusqu’&#224; ce qu’ils soient d&#233;pens&#233;s ou que le forge&#226;me pr&#233;pare de nouveau ses sorts. S’il utilise ce pouvoir plusieurs fois, ses effets ne se cumulent pas. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#SOUVENIRMAGIQUE&quot; title=&quot;Le magus&quot;&gt;souvenir magique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Reforger (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Reforger_Sur_6&quot; href=&quot;#Reforger_Sur_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 11, le forge&#226;me peut, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, rendre un nombre de points de vie &#233;gal &#224; son niveau de magus &#224; un objet ab&#238;m&#233;. Pour cela, il doit le toucher et d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#RESERVEMAGIQUE&quot; title=&quot;Le magus&quot;&gt;r&#233;serve magique&lt;/a&gt;. Pour r&#233;parer un objet d&#233;truit, il lui faut une minute et du mat&#233;riel (1/4 de la valeur de vente de l’objet). L’objet restaur&#233; a alors 1 point de vie. Si le forge&#226;me veut restaurer l’enchantement d’un objet magique d&#233;truit, il doit d&#233;penser un nombre de points de r&#233;serve magique suppl&#233;mentaire &#233;gal au &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;Niveau de lanceur de sorts&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; de l’objet. Si le niveau de lanceur de sort de l’objet est inf&#233;rieur &#224; celui du forge&#226;me, ce dernier re&#231;oit un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt;, deux s’il est sup&#233;rieur (et aucun si l’objet magique s’av&#232;re &#234;tre son objet f&#233;tiche). Pour se d&#233;barrasser de ces niveaux n&#233;gatifs, le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; est de 10 + niveau de lanceur de sorts de l’objet. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#SCIENCEDUSOUVENIRMAGIQUE&quot; title=&quot;Le magus&quot;&gt;science du souvenir magique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Riposte destructrice (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Riposte_destructrice_Sur_7&quot; href=&quot;#Riposte_destructrice_Sur_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 16, quand un adversaire active un objet magique dans la zone contr&#244;l&#233;e par un forge&#226;me, il provoque une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt; qui permet au magus de l’attaquer ou de tenter de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Destruction.html&quot; title=&quot;destruction&quot;&gt;d&#233;truire l’objet&lt;/a&gt;. S’il parvient &#224; le d&#233;truire, ses effets sont annul&#233;s. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#RIPOSTER&quot; title=&quot;Le magus&quot;&gt;riposte&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Reconstruction instantan&#233;e (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Reconstruction_instantan&#233;e_Sur_8&quot; href=&quot;#Reconstruction_instantan&#233;e_Sur_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 19, le forge&#226;me peut reforger un objet d&#233;truit d’un simple contact, gr&#226;ce &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; qui ne provoque pas d’attaque d’opportunit&#233;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#ACCESAUXSORTSSUPERIEUR&quot; title=&quot;Le magus&quot;&gt;acc&#232;s aux sorts sup&#233;rieur&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Arcanes de magus conseill&#233;s&lt;a class=&quot;headeranchor&quot; id=&quot;Arcanes_de_magus_conseill&#233;s_9&quot; href=&quot;#Arcanes_de_magus_conseill&#233;s_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les arcanes qui viennent compl&#233;ter le forge&#226;me : &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Frappededissipation.html&quot; title=&quot;frappe de dissipation&quot;&gt;frappe de dissipation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Lamedediee.html&quot; title=&quot;lame d&#233;di&#233;e&quot;&gt;lame d&#233;di&#233;e&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Lamefantome.html&quot; title=&quot;lame fant&#244;me (arcane)&quot;&gt;lame fant&#244;me&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Lamelongueduree.html&quot; title=&quot;lame longue dur&#233;e&quot;&gt;lame longue dur&#233;e&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Lametueuse.html&quot; title=&quot;lame tueuse&quot;&gt;lame tueuse&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Precisionarcanique.html&quot; title=&quot;pr&#233;cision arcanique&quot;&gt;pr&#233;cision arcanique&lt;/a&gt;.
